using namespace mxpart_mod;
using namespace sprods_com_mod;

// Z. Bern, L. Dixon, D.A. Kosower, e-Print:hep-ph/9708239
// Eq10.6

std::complex<double> FFPPsc1(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  auto zab = [&za, &zb](int i1, int i2, int i3) {
    return za(i1, i2) * zb(i2, i3);
  };

  return (za(j4, j1) * za(j5, j2) - za(j2, j4) * za(j5, j1)) * zab(j5, j4, j3)
      / (za(j3, j4) * std::pow(za(j4, j1), 2) * za(j5, j6));
}

std::complex<double> FFPPsc2(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  auto zab = [&za, &zb](int i1, int i2, int i3) {
    return za(i1, i2) * zb(i2, i3);
  };

  return -0.5 * std::pow(zab(j5, j4, j3), 2) * za(j3, j2)
      / (za(j3, j4) * za(j4, j1) * za(j5, j6));
}

std::complex<double> FFPPsc3(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  return -0.5 * std::pow(za(j5, j2), 2)
      / (za(j2, j3) * za(j3, j4) * za(j4, j1) * za(j5, j6));
}

std::complex<double> FFPPsc4(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  auto zab2 = [&za, &zb](int i1, int i2, int i3, int i4) {
    return za(i1, i2) * zb(i2, i4) + za(i1, i3) * zb(i3, i4);
  };
  auto zab = [&za, &zb](int i1, int i2, int i3) {
    return za(i1, i2) * zb(i2, i3);
  };

  return za(j2, j4) * std::pow(za(j5, j1), 2) * zab2(j2, j3, j4, j1)
      / (za(j2, j3) * za(j3, j4) * std::pow(za(j4, j1), 2) * za(j5, j6))
      - za(j5, j2) * zab(j2, j1, j6) / (za(j2, j3) * za(j3, j4) * za(j4, j1));
}

std::complex<double> FFPPsc5(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  auto zab = [&za, &zb](int i1, int i2, int i3) {
    return za(i1, i2) * zb(i2, i3);
  };

  return -0.5 * za(j5, j6) * std::pow(zab(j2, j1, j6), 2)
      / (za(j2, j3) * za(j3, j4) * za(j4, j1));
}

std::complex<double> FFPPsc6(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
